struct ServiceProxy: ServiceApi {          // same conformance as the service
    let real: any ServiceApi
    let metrics: Metrics

    func call(_ request: Request) async throws -> Response {
        let started = ContinuousClock.now
        defer { metrics.record("call", ContinuousClock.now - started) }  // policy
        return try await real.call(request)     // delegate unchanged, errors kept
    }
}

