final class RecordingProtocol: URLProtocol {
    override class func canInit(with request: URLRequest) -> Bool { true }
    override func startLoading() {                         // every URL load
        Metrics.count(request.url)                         // policy: observe
        URLSession.shared.dataTask(with: request) { data, resp, err in
            self.client?.urlProtocol(self, didReceive: resp!, cacheStoragePolicy: .notAllowed)
            if let data { self.client?.urlProtocol(self, didLoad: data) }
            if let err { self.client?.urlProtocol(self, didFailWithError: err) }
            self.client?.urlProtocolDidFinishLoading(self)   // exactly once
        }.resume()
    }
}
